    Subject = apps.get_model("master", "Subject")
    Course = apps.get_model("master", "Course")
    Curriculum = apps.get_model("master", "CurriculumMapping")
    Enrollment = apps.get_model("admissions", "Enrollment")
    MarksEntry = apps.get_model("academics", "MarksEntry")

