    Semester.objects.filter(
        pk__in=[o.id for o in originals], program__isnull=True,
    ).delete()

    print(
        f"\n  master.0019: cloned {len(originals)} semester(s) across "
        f"{len(programs)} program(s) -> {len(clones)} rows."
    )
    print(f"  master.0019: repointed {counts}.")


